<template>
  <main class="feedback-page">
    <header class="feedback-header"><button type="button" class="icon-button" aria-label="返回" @click="back"><svg viewBox="0 0 24 24"><path d="m14 5-7 7 7 7"/></svg></button><h1>共创建议</h1><router-link to="/feedback?mine=1" class="header-mine">我的建议<span v-if="unread" class="unread-dot" aria-label="有新进度"></span></router-link></header>
    <template v-if="!route.params.id">
      <section class="feedback-hero"><div class="hero-track" aria-hidden="true"><i></i><i></i><i></i><b>＋</b></div><span class="eyebrow">和跑者一起，打磨每一程</span><h2>你的好想法，<br/>值得再往前一步。</h2><p>功能、界面，或一个小小的不顺手。<br/>一起把赛历变得更好。</p><button type="button" class="primary hero-submit" @click="startCompose">提个建议 <span aria-hidden="true">↗</span></button><div class="hero-stats"><span><b>{{ summary.published || 0 }}</b> 条公开建议</span><span><b>{{ summary.adopted || 0 }}</b> 个想法已采纳</span></div></section>
      <section class="participation"><span class="participation-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 10h16v4H4zm2 4v7h12v-7M12 10v11m0-11H8a3 3 0 1 1 3-3zm0 0h4a3 3 0 1 0-3-3z"/></svg></span><div><b>好建议，有回应，也有心意</b><p>采纳后由运营确认实物奖励，具体奖品见建议详情。投票是参考，不是领奖条件。</p></div></section>
      <section class="feedback-board" aria-label="建议列表">
        <nav class="feedback-tabs" aria-label="建议范围"><button type="button" :class="{on: !mine}" :aria-pressed="!mine" @click="setMine(false)">大家的建议</button><button type="button" :class="{on: mine}" :aria-pressed="mine" @click="setMine(true)">我的建议<span v-if="unread" class="unread-count">{{ unread > 99 ? '99+' : unread }}</span></button></nav>
        <div class="board-controls"><div class="category-chips" role="group" aria-label="建议分类"><button v-for="item in categories" :key="item.id" type="button" :class="{on: category === item.id}" :aria-pressed="category === item.id" @click="changeCategory(item.id)">{{ item.label }}</button></div><label class="sort-choice"><span class="sr-only">建议排序</span><select v-model="sort" @change="loadList(1)"><option value="hot">热门优先</option><option value="new">最新发布</option><option value="adopted">已采纳</option></select></label></div>
        <p v-if="mine" class="board-note">待审核内容仅自己可见。官方回复和奖励进度，也会更新在这里。</p>
        <div v-if="loading" class="feedback-state" role="status"><span class="state-orbit" aria-hidden="true"></span><h3>正在收集大家的好想法</h3><p>请稍候…</p></div>
        <div v-else-if="error" class="feedback-state" role="alert"><h3>建议暂时没能加载</h3><p>{{ error }}</p><button type="button" class="secondary" @click="loadList(page)">重新加载</button></div>
        <template v-else><div v-if="!items.length" class="feedback-state"><span class="empty-idea" aria-hidden="true">＋</span><h3>{{ mine ? '第一个好想法，从你开始' : '这里正等待一个好想法' }}</h3><p>{{ sort === 'adopted' ? '被采纳的建议会在这里留下进展。' : mine ? '发现不顺手的地方，或有想要的新功能，随时告诉我们。' : '暂时没有这个分类的公开建议，换个分类看看，或留下你的想法。' }}</p><button type="button" class="secondary" @click="startCompose">提个建议</button></div><article v-for="item in items" :key="item.id" class="feedback-card"><router-link :to="'/feedback/' + item.id" class="card-main"><div class="card-meta"><span :class="['category-tag', item.category]">{{ categoryLabel(item.category) }}</span><span :class="['status-tag', item.status]">{{ item.statusLabel }}</span><i v-if="item.unread" class="unread-dot" aria-label="有新进度"></i></div><h3>{{ item.title }}</h3><p v-if="item.body" class="card-excerpt">{{ item.body }}</p><p v-if="item.reply" class="card-reply"><b>官方回应</b>{{ item.reply }}</p><div class="card-bottom"><span>{{ item.author?.nickname || '跑友' }}<i>·</i>{{ shortDate(item.createdAt) }}</span><span>{{ moduleLabel(item.module) }} <b aria-hidden="true">›</b></span></div></router-link><button type="button" :class="['card-vote', {voted:item.voted}]" :disabled="busyId === item.id || item.isMine || item.status !== 'published'" :aria-label="voteLabel(item)" :aria-pressed="!!item.voted" @click="vote(item)"><svg viewBox="0 0 24 24"><path d="m7 12 5-5 5 5M7 17l5-5 5 5"/></svg><b>{{ item.votes || 0 }}</b><span>{{ item.isMine ? '我的' : item.status !== 'published' ? '支持' : item.voted ? '已支持' : '支持' }}</span></button></article><nav v-if="pages > 1" class="feedback-pagination" aria-label="建议分页"><button type="button" class="secondary" :disabled="page <= 1 || loading" @click="loadList(page - 1)">上一页</button><span>{{ page }} / {{ pages }}</span><button type="button" class="secondary" :disabled="page >= pages || loading" @click="loadList(page + 1)">下一页</button></nav></template>
      </section>
      <p class="feedback-rule">提交 → 审核公示 → 跑友投票 → 评估采纳 → 更新进度</p>
      <div class="feedback-bottom"><span>每个更好的体验，都从一个想法开始</span><button type="button" class="primary" @click="startCompose">＋ 提个建议</button></div>
    </template>
    <template v-else>
      <div v-if="loading" class="feedback-state" role="status"><span class="state-orbit" aria-hidden="true"></span><h3>正在打开这份好想法</h3></div>
      <div v-else-if="error" class="feedback-state" role="alert"><h3>{{ missing ? '这条建议暂不可查看' : '暂时没能加载建议' }}</h3><p>{{ error }}</p><button v-if="!missing" type="button" class="secondary" @click="loadDetail">重新加载</button><router-link class="primary" to="/feedback">返回建议板</router-link></div>
      <article v-else-if="detail" class="feedback-detail">
        <section class="detail-content"><div class="card-meta"><span :class="['category-tag', detail.category]">{{ categoryLabel(detail.category) }}</span><span :class="['status-tag', detail.status]">{{ detail.statusLabel }}</span><span class="module-tag">{{ moduleLabel(detail.module) }}</span></div><h2>{{ detail.title }}</h2><p class="detail-byline"><span class="author-avatar" aria-hidden="true">{{ (detail.author?.nickname || '跑').slice(0, 1) }}</span>{{ detail.author?.nickname || '跑友' }}<i>·</i>{{ dateTime(detail.createdAt) }}</p><p class="detail-body">{{ detail.body }}</p><div v-if="detail.images?.length" class="feedback-images"><div v-for="item in detail.images" :key="item.id" class="feedback-image"><button type="button" @click="previewImage(item.url)"><img :src="item.url" alt="建议附图，点击查看大图"/></button><button v-if="detail.isMine && detail.status === 'pending'" type="button" class="image-remove" :disabled="busy" :aria-label="'删除附图 ' + item.id" @click="removeImage(item.id)">×</button></div></div><label v-if="detail.isMine && detail.status === 'pending' && (detail.images?.length || 0) < 3" class="attachment-action"><span>＋ 补充截图</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="busy" @change="addDetailImages"/></label><p v-if="detail.status === 'pending'" class="private-note">审核前仅你自己可见，通过审核后再向跑友公示。</p><div class="detail-actions"><button v-if="isPublic" type="button" class="text-button" @click="share">分享这个想法 ↗</button><button v-if="detail.canWithdraw" type="button" class="text-button muted" :disabled="busy" @click="confirmWithdraw">撤回建议</button></div></section>
        <section class="official-card"><div class="section-heading"><span class="official-symbol" aria-hidden="true">S</span><div><h3>每个想法，都有下文</h3><p>赛历产品团队 · 进度公开</p></div></div><div v-if="detail.reply" class="official-reply"><b>官方回应</b><p>{{ detail.reply }}</p></div><p v-else class="progress-placeholder">{{ detail.status === 'pending' ? '我们会先核对内容，审核通过后公开征集跑友意见。' : detail.status === 'withdrawn' ? '你已撤回这条建议，不再公开展示。' : '正在听取跑友的声音，评估结果将在这里更新。' }}</p><ol class="feedback-timeline"><li v-for="(event, index) in detail.events || []" :key="index" :class="{latest:index === (detail.events?.length || 0) - 1}"><span class="timeline-point"></span><div><b>{{ event.statusLabel }}</b><time>{{ dateTime(event.createdAt) }}</time><p v-if="event.reply">{{ event.reply }}</p></div></li></ol></section>
        <section v-if="detail.reward" class="feedback-reward"><div class="reward-top"><span class="reward-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 10h16v4H4zm2 4v7h12v-7M12 10v11m0-11H8a3 3 0 1 1 3-3zm0 0h4a3 3 0 1 0-3-3z"/></svg></span><div><span class="eyebrow">给好想法，一份奔跑的心意</span><h3>{{ detail.reward.name }}</h3></div><span class="reward-status">{{ detail.reward.statusLabel }}</span></div><template v-if="detail.isMine"><p class="reward-description">感谢你让赛历更好。收件信息仅你本人和平台管理员可见，用于寄送这份奖励。</p><div v-if="detail.reward.status === 'shipped' || detail.reward.status === 'received'" class="shipping-info"><p><span>配送信息</span><b>{{ detail.reward.carrier }} · {{ detail.reward.tracking }}</b></p><p><span>收件人</span><b>{{ detail.reward.receiver }} · {{ detail.reward.phone }}</b></p><p><span>收件地址</span><b>{{ detail.reward.address }}</b></p><button v-if="detail.reward.status === 'shipped'" type="button" class="primary" :disabled="busy" @click="confirmReceived">确认已收到奖励</button><p v-else class="received-note">奖励已签收，期待你的下一个好想法。</p></div><template v-else><button v-if="!claimOpen" type="button" class="primary reward-claim" @click="openClaim">{{ detail.reward.status === 'claimed' ? '查看 / 修改收件信息' : '填写收件信息，领取奖励' }}</button><form v-if="claimOpen" class="reward-form" @submit.prevent="saveClaim"><label>收件人<input v-model="claim.receiver" autocomplete="shipping name" minlength="2" maxlength="40" required placeholder="真实姓名，用于快递配送"/></label><label>手机号码<input v-model="claim.phone" type="tel" inputmode="numeric" autocomplete="shipping tel" maxlength="11" required placeholder="中国大陆 11 位手机号码"/></label><label>收件地址<textarea v-model="claim.address" autocomplete="shipping street-address" minlength="8" maxlength="300" rows="3" required placeholder="省、市、区及详细地址"/></label><label class="consent"><input v-model="claim.consent" type="checkbox" required/><span>我同意平台仅为寄送本次奖励使用以上收件信息。</span></label><div class="form-actions"><button type="button" class="secondary" :disabled="busy" @click="claimOpen = false">取消</button><button type="submit" class="primary" :disabled="busy">{{ busy ? '正在保存…' : '保存收件信息' }}</button></div></form></template></template><p v-else class="reward-description">这条想法已获采纳，作者将获得运营确认的实物奖励。</p></section>
        <p class="feedback-rule">投票帮助我们了解需求；采纳同时考虑实用性、可行性和产品规划。</p>
        <div class="feedback-bottom detail-bottom"><div><b>{{ detail.votes || 0 }} <small>位跑友支持</small></b><span>{{ detail.isMine ? '这是你为赛历提出的好想法' : detail.status === 'published' ? '如果你也需要，就为它投一票' : '这条建议已结束投票' }}</span></div><button type="button" :class="['primary', 'feedback-vote', {voted:detail.voted}]" :disabled="busy || detail.isMine || detail.status !== 'published'" :aria-pressed="!!detail.voted" @click="vote(detail)">{{ detail.isMine ? '我的建议' : detail.status !== 'published' ? detail.statusLabel : detail.voted ? '已支持 · 取消' : '为它投一票' }}</button></div>
      </article>
    </template>
    <p v-if="notice" class="feedback-toast" role="status">{{ notice }}</p>
    <dialog ref="composeDialog" class="feedback-dialog feedback-form" @cancel="closeCompose"><form @submit.prevent="submit"><header class="dialog-header"><div><span class="eyebrow">让下次使用，更顺手一点</span><h2>留一个好想法</h2></div><button type="button" class="icon-button" aria-label="关闭建议表单" :disabled="busy" @click="closeCompose">×</button></header><label>你想改进哪一类体验？<div class="compose-categories"><button v-for="item in categories.filter(x => x.id !== 'all')" :key="item.id" type="button" :class="{on:form.category === item.id}" :aria-pressed="form.category === item.id" @click="form.category = item.id">{{ item.label }}</button></div></label><label>标题<span class="field-count">{{ form.title.length }}/80</span><input v-model="form.title" minlength="4" maxlength="80" required placeholder="一句话，说说你想要的改变"/></label><label>具体说说<span class="field-count">{{ form.body.length }}/3000</span><textarea v-model="form.body" rows="6" minlength="10" maxlength="3000" required placeholder="你在什么场景遇到了问题？希望怎么改？对跑友有什么帮助？"/></label><label class="module-choice">相关页面<select v-model="form.module"><option v-for="item in modules" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><div class="compose-attachments"><div class="attachment-head"><span>补充截图 <small>选填，最多 3 张</small></span><label v-if="attachments.length < 3" class="attachment-action">＋ 选择图片<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="chooseImages"/></label></div><div v-if="attachments.length" class="attachment-previews"><div v-for="(item, index) in attachments" :key="item.url"><img :src="item.url" alt="待提交截图"/><button type="button" :aria-label="'移除第 ' + (index + 1) + ' 张截图'" @click="removeAttachment(index)">×</button></div></div><p>支持 JPG、PNG、WebP，单张不超过 5MB。请勿上传身份证、电话、住址等个人信息。</p></div><p class="draft-note">文字自动保存为本账号草稿，截图需重新选择。提交后先审核，再公示。</p><p v-if="formError" class="form-error" role="alert">{{ formError }}</p><div class="form-actions"><button type="button" class="secondary" :disabled="busy" @click="closeCompose">存为草稿</button><button type="submit" class="primary" :disabled="busy">{{ busy ? '正在提交…' : '提交建议' }}</button></div></form></dialog>
    <dialog ref="confirmDialog" class="feedback-dialog confirm-dialog" @cancel="cancelConfirm"><h2>{{ confirmTitle }}</h2><p>{{ confirmBody }}</p><div class="form-actions"><button type="button" class="secondary" @click="cancelConfirm">再想想</button><button type="button" class="primary" @click="acceptConfirm">{{ confirmAction }}</button></div></dialog>
    <dialog ref="imageDialog" class="feedback-dialog image-dialog"><button type="button" class="icon-button" aria-label="关闭大图" @click="imageDialog.close()">×</button><img v-if="preview" :src="preview" alt="建议附图大图"/></dialog>
  </main>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, upload } from '../api';
const route = useRoute(), router = useRouter();
const categories = [{id:'all',label:'全部'},{id:'feature',label:'功能建议'},{id:'ui',label:'界面体验'},{id:'bug',label:'问题反馈'},{id:'other',label:'其他想法'}];
const modules = [{id:'other',label:'其他 / 通用'},{id:'races',label:'赛事'},{id:'clubs',label:'跑团'},{id:'sport',label:'运动'},{id:'profile',label:'我的 / 跑者档案'}];
const categoryLabel = id => categories.find(x => x.id === id)?.label || '其他想法';
const moduleLabel = id => modules.find(x => x.id === id)?.label || '其他 / 通用';
const items = ref([]), detail = ref(null), summary = ref({published:0,adopted:0}), unread = ref(0);
const mine = ref(route.query.mine === '1'), category = ref('all'), sort = ref('hot'), page = ref(1), pages = ref(1), loading = ref(true), error = ref(''), missing = ref(false);
const busy = ref(false), busyId = ref(null), notice = ref('');
const composeDialog = ref(null), confirmDialog = ref(null), imageDialog = ref(null), preview = ref('');
const form = reactive({title:'',body:'',category:'feature',module:'other'}), formError = ref(''), attachments = ref([]);
const claimOpen = ref(false), claim = reactive({receiver:'',phone:'',address:'',consent:false});
const confirmTitle = ref(''), confirmBody = ref(''), confirmAction = ref('确认');
const isPublic = computed(() => !!detail.value?.publishedAt && !['pending','withdrawn'].includes(detail.value.status));
let requestId = 0, actionId = 0, composeId = 0, noticeTimer, draftKey = '', composeBusy = false, confirmed = null, alive = true;
const token = () => localStorage.getItem('marathon_token') || '';
function beginAction() { busy.value = true; return {id:++actionId,session:token()}; }
function currentAction(action) { return alive && action.id === actionId && action.session === token(); }
function finishAction(action) { if (currentAction(action)) { busy.value = false; busyId.value = null; } }
function shortDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',timeZone:'Asia/Shanghai'}).format(date); }
function dateTime(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(date); }
function tell(value) { notice.value = value; clearTimeout(noticeTimer); noticeTimer = setTimeout(() => { notice.value = ''; }, 5000); }
function login(returnPath = route.fullPath) { localStorage.setItem('marathon_return_after_login',returnPath); router.push('/mine'); }
function recover(err, returnPath = route.fullPath) { if (err.status !== 401) return false; localStorage.removeItem('marathon_token'); localStorage.removeItem('marathon_name'); login(returnPath); return true; }
function back() { router.push(route.params.id ? '/feedback' : '/mine'); }
async function loadList(next = 1) {
  if (mine.value && !token()) { login('/feedback?mine=1'); return; }
  const id = ++requestId, session = token(); loading.value = true; error.value = '';
  try { const data = await api('/feedback?' + new URLSearchParams({category:category.value,sort:sort.value,page:String(next),mine:mine.value?'1':'0'})); if (!alive || id !== requestId || token() !== session) return; items.value = data.items || []; summary.value = data.summary || summary.value; unread.value = data.unread || 0; page.value = data.page || next; pages.value = data.pages || 1; }
  catch (err) { if (alive && id === requestId && token() === session && !recover(err)) error.value = err.message; }
  finally { if (alive && id === requestId && token() === session) loading.value = false; }
}
async function loadDetail() {
  const id = ++requestId, session = token(); loading.value = true; error.value = ''; missing.value = false; detail.value = null;
  try { const data = await api('/feedback/' + encodeURIComponent(route.params.id)); if (!alive || id !== requestId || token() !== session) return; detail.value = data; if (data.isMine && data.unread) { const acknowledged = await api('/feedback/' + data.id + '/read',{method:'POST',body:JSON.stringify({revision:data.revision})}).then(() => true).catch(() => false); if (acknowledged && alive && id === requestId && token() === session && detail.value?.id === data.id) detail.value.unread = false; } }
  catch (err) { if (alive && id === requestId && token() === session) { missing.value = err.status === 404; error.value = err.status === 404 ? '建议可能还在审核中，或已由作者撤回。' : err.message; } }
  finally { if (alive && id === requestId && token() === session) loading.value = false; }
}
function setMine(value) { if (value && !token()) return login('/feedback?mine=1'); router.replace({path:'/feedback',query:value?{mine:'1'}:{}}); }
function changeCategory(value) { category.value = value; loadList(1); }
async function vote(item) {
  if (!token()) return login('/feedback/' + item.id);
  if (busy.value || busyId.value || item.isMine || item.status !== 'published') return;
  const action = beginAction(); busyId.value = item.id;
  try { const updated = await api('/feedback/' + item.id + '/vote',{method:'PUT',body:JSON.stringify({voted:!item.voted})}); if (!currentAction(action)) return; if (detail.value?.id === updated.id) detail.value = updated; items.value = items.value.map(x => x.id === updated.id ? updated : x); tell(updated.voted ? '谢谢支持，你的这一票已记下。' : '已取消支持'); }
  catch (err) { if (currentAction(action) && !recover(err,'/feedback/' + item.id)) tell(err.message); }
  finally { finishAction(action); }
}
function voteLabel(item) { return (item.isMine ? '我的建议' : item.status !== 'published' ? '支持人数' : item.voted ? '取消支持' : '支持建议') + '：' + item.title + '，' + (item.votes || 0) + ' 票'; }
async function startCompose() {
  if (!token()) return login('/feedback?compose=1');
  if (composeBusy || composeDialog.value?.open) return;
  composeBusy = true; const session = token(), id = ++composeId; formError.value = '';
  try { const me = await api('/me'); if (!alive || id !== composeId || token() !== session) return; draftKey = 'marathon_feedback_draft_' + me.user.id; let saved = {}; try { saved = JSON.parse(localStorage.getItem(draftKey) || '{}'); } catch {} Object.assign(form,{title:String(saved.title || '').slice(0,80),body:String(saved.body || '').slice(0,3000),category:categories.some(x=>x.id === saved.category && x.id !== 'all')?saved.category:'feature',module:modules.some(x=>x.id === saved.module)?saved.module:'other'}); await nextTick(); if (alive && id === composeId && token() === session) composeDialog.value.showModal(); }
  catch (err) { if (alive && id === composeId && token() === session && !recover(err,'/feedback?compose=1')) tell(err.message); }
  finally { if (alive && id === composeId && token() === session) composeBusy = false; }
}
function closeCompose(event) { if (busy.value) { event?.preventDefault(); return; } composeDialog.value?.close(); if (route.query.compose) router.replace({path:route.path,query:mine.value?{mine:'1'}:{}}); }
watch(form, () => { if (!draftKey) return; try { localStorage.setItem(draftKey,JSON.stringify({...form})); } catch {} });
function checkedFiles(files, limit) { const chosen = []; for (const file of files) { if (!['image/jpeg','image/png','image/webp'].includes(file.type)) throw new Error('请选择 JPG、PNG 或 WebP 图片'); if (!file.size || file.size > 5 * 1024 * 1024) throw new Error('每张截图须大于 0 且不超过 5MB'); chosen.push(file); } if (chosen.length > limit) throw new Error('一条建议最多添加 3 张截图'); return chosen; }
function chooseImages(event) { try { for (const file of checkedFiles([...event.target.files],3 - attachments.value.length)) attachments.value.push({file,url:URL.createObjectURL(file)}); formError.value = ''; } catch (err) { formError.value = err.message; } event.target.value = ''; }
function removeAttachment(index) { URL.revokeObjectURL(attachments.value[index].url); attachments.value.splice(index,1); }
function clearAttachments() { attachments.value.forEach(x => URL.revokeObjectURL(x.url)); attachments.value = []; }
async function submit() {
  if (busy.value) return; formError.value = '';
  if (form.title.trim().length < 4 || form.body.trim().length < 10) { formError.value = '标题至少 4 个字，具体描述至少 10 个字。'; return; }
  const action = beginAction();
  try { const created = await api('/feedback',{method:'POST',body:JSON.stringify({...form,title:form.title.trim(),body:form.body.trim()})}); if (!currentAction(action)) return; let failed = 0; for (const entry of attachments.value) { if (!currentAction(action)) return; try { await upload('/feedback/' + created.id + '/images',entry.file); } catch { failed++; } } if (!currentAction(action)) return; try { localStorage.removeItem(draftKey); } catch {} draftKey = ''; clearAttachments(); composeDialog.value.close(); await router.push('/feedback/' + created.id + (failed ? '?attachmentError=1' : '?submitted=1')); }
  catch (err) { if (currentAction(action) && !recover(err,'/feedback?compose=1')) formError.value = err.message; }
  finally { finishAction(action); }
