function previewImage(url) { preview.value = url; imageDialog.value.showModal(); }
function ask(title,body,action,callback) { confirmTitle.value = title; confirmBody.value = body; confirmAction.value = action; confirmed = callback; confirmDialog.value.showModal(); }
function cancelConfirm() { confirmed = null; confirmDialog.value.close(); }
function acceptConfirm() { const action = confirmed; confirmed = null; confirmDialog.value.close(); action?.(); }
function confirmWithdraw() { ask('撤回这条建议？','撤回后将停止公示和投票；原有内容会保留在你的建议中。','确认撤回',async () => { if (busy.value || !detail.value) return; const action = beginAction(), id = detail.value.id; try { const updated = await api('/feedback/' + id + '/withdraw',{method:'POST'}); if (!currentAction(action)) return; detail.value = updated; tell('建议已撤回'); } catch (err) { if (currentAction(action) && !recover(err)) tell(err.message); } finally { finishAction(action); } }); }
function openClaim() { Object.assign(claim,{receiver:detail.value.reward.receiver || '',phone:detail.value.reward.phone || '',address:detail.value.reward.address || '',consent:false}); claimOpen.value = true; }
async function saveClaim() { if (busy.value || !detail.value) return; if (!/^1[3-9]\d{9}$/.test(claim.phone.trim())) return tell('请输入有效的中国大陆手机号码'); if (!claim.consent) return tell('请先同意仅为本次奖励使用收件信息'); const action = beginAction(), id = detail.value.id; try { const updated = await api('/feedback/' + id + '/reward/claim',{method:'PUT',body:JSON.stringify({...claim,receiver:claim.receiver.trim(),phone:claim.phone.trim(),address:claim.address.trim()})}); if (!currentAction(action)) return; detail.value = updated; claimOpen.value = false; Object.assign(claim,{receiver:'',phone:'',address:'',consent:false}); tell('收件信息已保存，运营寄出后可在这里查看物流。'); } catch (err) { if (currentAction(action) && !recover(err)) tell(err.message); } finally { finishAction(action); } }
